'use client';
import {useEffect,useRef,useState} from 'react';
import {hotelRpc,formText} from '@/lib/pilot';
type Person={user_id:string;email:string;role:string;is_self:boolean};
export function StaffPanel({tenant,property,role}:{tenant:string;property:string;role:string}){
 const [rows,setRows]=useState<Person[]>([]),[error,setError]=useState(''),[notice,setNotice]=useState(''),[busy,setBusy]=useState(false),[remove,setRemove]=useState<Person|null>(null);
 const request=useRef<{key:string;id:string}|null>(null);
 async function load(){setRows(await hotelRpc<Person[]>('staff',{p_tenant:tenant,p_property:property}))}
 useEffect(()=>{let live=true;if(role==='owner')hotelRpc<Person[]>('staff',{p_tenant:tenant,p_property:property}).then(r=>live&&setRows(r)).catch(e=>live&&setError(e.message));return()=>{live=false}},[tenant,property,role]);
 async function run(fn:()=>Promise<void>){setBusy(true);setError('');setNotice('');try{await fn();request.current=null;setNotice('Staff access saved.');try{await load()}catch{setError('Access was saved, but the list could not refresh. Refresh the workspace.')}}catch(e){setError(e instanceof Error?e.message:'Unable to update staff')}finally{setBusy(false)}}
 function id(key:string){if(request.current?.key!==key)request.current={key,id:crypto.randomUUID()};return request.current.id}
 if(role!=='owner')return <section className="card pilot-empty">Only an organization owner can manage staff access.</section>;
 return <section className="card pilot-settings"><h2>Organization staff</h2><p>Manage organization accounts here. Team members must first create and confirm their own account. Where property access is enabled, assign their properties separately below.</p>{error&&<div className="pilot-error" role="alert">{error}</div>}{notice&&<output className="pilot-notice">{notice}</output>}<form onSubmit={e=>{e.preventDefault();const form=e.currentTarget,f=new FormData(form),email=formText(f,'email').trim().toLowerCase(),nextRole=formText(f,'role');void run(async()=>{await hotelRpc('save_member',{p_tenant:tenant,p_property:property,p_request:id(email+'/'+nextRole),p_email:email,p_role:nextRole});form.reset()})}}><label className="field">Confirmed account email<input name="email" type="email" required/></label><label className="field">Access level<select name="role"><option value="staff">Staff — reservations and housekeeping</option><option value="manager">Manager — includes property configuration</option></select></label><button className="primary" disabled={busy}>Add or update staff</button></form><div className="pilot-staff-list">{rows.map(p=><div className="pilot-list-row" key={p.user_id}><div><strong>{p.email}{p.is_self?' (you)':''}</strong><small>{p.role}</small></div><button className="text-button" disabled={busy} onClick={()=>setRemove(p)}>Remove…</button></div>)}</div>{remove&&<div className="pilot-error"><p>Remove {remove.email} from this organization? Their access to all its properties will be revoked.</p><div className="pilot-actions"><button className="secondary" disabled={busy} onClick={()=>setRemove(null)}>Keep access</button><button className="primary" disabled={busy} onClick={()=>void run(async()=>{await hotelRpc('remove_member',{p_tenant:tenant,p_property:property,p_request:id('remove/'+remove.user_id),p_user:remove.user_id});setRemove(null)})}>Remove access</button></div></div>}</section>
}

